from taf.ul.mobile.ui.android.mobiles.huawei import (MagicUI311HonorCdyAn900, EMUI1010HuaWeiLioAn00,
                                                     MagicUI311HonorCdyAn95, EMUI1010HuaweiEvrAn900,
                                                     EMUI1100HuaWeiLioAn00, HarmonyOs300HonorCdyAn90,
                                                     HarmonyOs300HonorCdyAn95)
from taf.ul.mobile.ui.android.mobiles.mediatek import (PetrusAlpsK6885V164, PetrusAlpsK6889v164NaAtt,
                                                       PetrusAlpsK6885v164WwMp3R3mdFtmdPre,
                                                       PetrusAlpsK6885v164AttVzwDsR3md,
                                                       PetrusAlpsK6885v164Na, PetrusAlpsK6889v164NaCcp,
                                                       PetrusAlpsK6885v164NaNewBwMp7md)
from taf.ul.mobile.ui.android.mobiles.qualcomm import (QtiLahainaforarm64, QtiTaroforarm64,
                                                       QtiKalamaforarm64, QtiPineappleforarm64)
from taf.ul.mobile.ui.android.mobiles.samsung import (OneUi31Galaxxys21SmG996u, OneUi31Galaxxys21SmG986u,
                                                      OneUi31Galaxxys21SmS901u, OneUi31Galaxxys21SmG998u,
                                                      OneUi31Galaxxys21SmS908u, OneUi51Galaxxys21SmS911u,
                                                      OneUi40Galaxxys23SmG991u, OneUi40Galaxxys21SmG996u,
                                                      OneUi51Galaxxys24SmS921u)
from taf.ul.mobile.ui.android.exceptions import MobileBrandNotSupported


class SupportedMobiles(object):

    _mobiles = {'magic ui 3.1.1_honor_cdy-an90': MagicUI311HonorCdyAn900,
                'emui 10.1.0_huawei_lio-an00': EMUI1010HuaWeiLioAn00,
                'magic ui 3.1.1_honor_cdy-an95': MagicUI311HonorCdyAn95,
                'emui 10.0.0_huawei_evr-an00': EMUI1010HuaweiEvrAn900,
                'emui 11.0.0_huawei_lio-an00': EMUI1100HuaWeiLioAn00,
                'petrus_alps_k6885v1_64': PetrusAlpsK6885V164,
                'petrus_alps_k6889v1_64_na_att': PetrusAlpsK6889v164NaAtt,
                'petrus_alps_k6885v1_64_ww_mp3_r3md_ftmd_pre': PetrusAlpsK6885v164WwMp3R3mdFtmdPre,
                'petrus_alps_k6885v1_64_att_vzw_ds_r3md': PetrusAlpsK6885v164AttVzwDsR3md,
                'petrus_alps_k6885v1_64_na': PetrusAlpsK6885v164Na,
                'petrus_alps_k6889v1_64_na_ccp': PetrusAlpsK6889v164NaCcp,
                'petrus_alps_k6885v1_64_na_new_bw_mp7md': PetrusAlpsK6885v164NaNewBwMp7md,
                "_qti_lahainaforarm64": QtiLahainaforarm64,
                "_qti_taroforarm64": QtiTaroforarm64,
                "_qti_kalamaforarm64": QtiKalamaforarm64,
                "_qti_pineappleforarm64": QtiPineappleforarm64,
                "one ui 3.1_samsung_sm-g996u": OneUi31Galaxxys21SmG996u,
                "one ui 3.1_samsung_sm-g986u": OneUi31Galaxxys21SmG986u,
                "one ui 3.1_samsung_sm-s901u": OneUi31Galaxxys21SmS901u,
                "one ui 3.1_samsung_sm-g998u": OneUi31Galaxxys21SmG998u,
                "one ui 3.1_samsung_sm-s908u": OneUi31Galaxxys21SmS908u,
                "one ui 5.1_samsung_sm-s911u": OneUi51Galaxxys21SmS911u,
                "one ui 4.0_samsung_sm-g991u": OneUi40Galaxxys23SmG991u,
                "one ui 4.0_samsung_sm-g996u": OneUi40Galaxxys21SmG996u,
                "one ui 5.1_samsung_sm-s921u": OneUi51Galaxxys24SmS921u,
                "harmonyos 3.0.0_honor_cdy-an90": HarmonyOs300HonorCdyAn90,
                "harmonyos 3.0.0_honor_cdy-an95": HarmonyOs300HonorCdyAn95}

    def get_mobile(self, ui_version, brand, model):
        try:
            ui_version = ui_version if ui_version else ""
            mobile_name = "{}_{}_{}".format(ui_version, brand, model)
            mobile_name = mobile_name.lower()
            return self._mobiles[mobile_name]
        except AttributeError:
            raise MobileBrandNotSupported('ui={} brand={} model={} not supported'.format(ui_version, brand, model))
